# Software Dependency Graph Builder - runnable demo (JAH-ATK191S-000001)
RANK = 1
SIG = True
MANIFESTS = {'app': ['web', 'db'], 'web': ['http'], 'db': ['driver'], 'http': [], 'driver': []}  # {package: [deps]}
graph = dict(MANIFESTS)
print("packages:", len(graph))
for pkg, deps in graph.items():
    print("  %-8s -> %s" % (pkg, deps if deps else "(leaf)"))
def find_cycle():
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {p: WHITE for p in graph}
    def dfs(u, path):
        color[u] = GRAY
        for v in graph.get(u, []):
            if v not in color: continue
            if color[v] == GRAY: return path + [v]
            if color[v] == WHITE:
                r = dfs(v, path + [v])
                if r: return r
        color[u] = BLACK
        return None
    for p in graph:
        if color[p] == WHITE:
            r = dfs(p, [p])
            if r: return r
    return None
cyc = find_cycle()
print("cycle:", " -> ".join(cyc) if cyc else "none")
if RANK >= 3:
    leaves = [p for p, d in graph.items() if not d]
    print("leaf packages:", leaves)
if SIG:
    print("Signature lineage stamp: JAH-SIG-DEP-" + "JAH-ATK191S-000001")
print("record:", "JAH-ATK191S-000001", "OK")

